INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 19, 'theory', 'Quiz: cloud drive');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 19, 0, 'Why are file contents and metadata stored in different systems?', '["That''s just the convention", "Metadata is small and changes often (database, cache), content is huge and immutable (object storage)", "Databases cannot store numbers", "To complicate the system"]', 1, 'They differ in volume, load, and requirements: the database is fast and small, while storage grows independently and gets cheaper.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 19, 1, 'What does splitting a file into blocks with a content hash give you?', '["Only encryption", "Resumable upload, delta sync, and deduplication of identical blocks", "Only a faster disk", "Nothing"]', 1, 'Identical blocks are stored once, and changing part of a file requires transferring only the affected blocks.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 19, 2, 'Why do blocks cache well in a CDN?', '["They are small", "They are addressed by hash and immutable, so the cache never goes stale", "A CDN stores only blocks", "They are encrypted"]', 1, 'Content by hash never changes, so the TTL can be very long.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 19, 3, 'How does a client catch up on changes after a dropped connection?', '["It downloads everything again", "It requests a delta by cursor, the number of the last known change", "It waits for a new signal", "It doesn''t"]', 1, 'The cursor says which changes the client has already seen, so nothing is lost.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 19, 4, 'How is the main cost of a cloud drive, storage, reduced?', '["By buying servers", "With storage classes by age, deduplication, and erasure coding instead of three copies", "By turning off monitoring", "By raising the cache TTL"]', 1, 'Cold storage is cheaper, deduplication removes repeats, and erasure coding gives durability at ~1.5x instead of 3x.');
